  "image_category": "SIGN_ILLUSTRATION",
  "summary": "Hình ảnh minh họa ba kiểu biển số W.207 (a, b, c) thuộc nhóm 'Giao nhau với đường không ưu tiên (đường nhánh)' theo QCVN 41:2024/BGTVT, dùng để báo trước nơi giao nhau trên đường ưu tiên.",
  "items": [
    {
      "identifier": "Biển số W.207a",
      "visual_or_geometric_features": "Hình tam giác đều, viền đỏ, nền vàng, biểu tượng đen: mũi tên chỉ hướng trái và dấu cộng chéo (giao nhau với đường không ưu tiên)",
      "meaning_or_specification": "Đặt trên đường ưu tiên để báo trước sắp đến nơi giao nhau với đường không ưu tiên; xe đi trên đường này được quyền ưu tiên qua nơi giao nhau, chỉ phải nhường đường cho xe ưu tiên theo quy định."
    },
    {
      "identifier": "Biển số W.207b",
      "visual_or_geometric_features": "Hình tam giác đều, viền đỏ, nền vàng, biểu tượng đen: mũi tên chỉ hướng phải và dấu cộng chéo (giao nhau với đường không ưu tiên)",
      "meaning_or_specification": "Tương tự W.207a nhưng dành cho trường hợp giao nhau với đường không ưu tiên theo hướng phải; đặt trước nơi giao nhau ở ngoài phạm vi nội thành, nội thị."
    },
    {
      "identifier": "Biển số W.207c",
      "visual_or_geometric_features": "Hình tam giác đều, viền đỏ, nền vàng, biểu tượng đen: mũi tên chỉ hướng phải và dấu cộng chéo (giao nhau với đường không ưu tiên)",
      "meaning_or_specification": "Tương tự W.207b; được đặt trên tất cả các nhánh đường giao với đoạn đường ưu tiên (giữa biển I.401 và I.402) ở nơi giao nhau."
    }
  ]
}
